const TOOLS = ["READ_MARKET", "READ_TRANSACTION", "READ_BORROWER_HISTORY", "CHECK_ORACLE_SOURCES", "VERIFY_BLOCKS"] as const;
export type LiveTool = typeof TOOLS[number];
const actionSchema = z.object({ action: z.enum([...TOOLS, "FINALIZE"]), reason: z.string().min(1).max(800) }).strict();
export interface LiveAgentReport {
