      if (report.status !== "COMPLETED") report.findings.push("Investigation incomplete; preserve the evidence and request review.");
      report.completedAt = new Date().toISOString();
      report.traceId = neatlogs.getLatestTrace()?.traceId;
      return report;
    });
  }
}
